function renderMenu(category){const data=menuData[category];$('#menu-items').replaceChildren();for(const item of data.items){const article=document.createElement('article');article.className='menu-item';if(item.note){const note=document.createElement('span');note.className='item-note';note.textContent=item.note;article.append(note)}const title=document.createElement('div');title.className='menu-item-title';const h=document.createElement('h3');h.textContent=item.name;title.append(h);if(item.price){const price=document.createElement('span');price.className='price';price.textContent=`R$ ${item.price}`;title.append(price)}const p=document.createElement('p');p.textContent=item.description;article.append(title,p);$('#menu-items').append(article)}if(category==='sobremesas'){const a=document.createElement('a');a.href='https://wa.me/5519995076736?text='+encodeURIComponent('Olá! Gostaria de conhecer as sobremesas disponíveis hoje no Pinho’s Bistrô.');a.target='_blank';a.rel='noopener noreferrer';a.className='text-link';a.textContent='Descobrir as sobremesas de hoje ↗';$('#menu-items').append(a)}$('#menu-photo').src=data.image;$('#menu-photo').alt=data.alt;$('#menu-photo-caption').textContent=data.caption;$('#photo-index').textContent=data.index;$('#menu-panel').setAttribute('aria-labelledby',`tab-${category}`);$$('[data-category]').forEach(b=>{const active=b.dataset.category===category;b.setAttribute('aria-selected',active);b.tabIndex=active?0:-1})}
renderMenu('principais');$$('[data-category]').forEach((b,i,buttons)=>{b.addEventListener('click',()=>renderMenu(b.dataset.category));b.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=(i+1)%buttons.length;if(e.key==='ArrowLeft')next=(i-1+buttons.length)%buttons.length;if(e.key==='Home')next=0;if(e.key==='End')next=buttons.length-1;if(next!==undefined){e.preventDefault();buttons[next].focus();renderMenu(buttons[next].dataset.category)}})});
const navToggle=$('.nav-toggle'),mobileNav=$('#mobile-nav');function closeNav(){mobileNav.hidden=true;navToggle.setAttribute('aria-expanded','false');navToggle.setAttribute('aria-label','Abrir menu')}
navToggle.addEventListener('click',()=>{const open=navToggle.getAttribute('aria-expanded')==='true';mobileNav.hidden=open;navToggle.setAttribute('aria-expanded',String(!open));navToggle.setAttribute('aria-label',open?'Abrir menu':'Fechar menu')});$$('a',mobileNav).forEach(a=>a.addEventListener('click',closeNav));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeNav()});document.addEventListener('click',e=>{if(!mobileNav.hidden&&!mobileNav.contains(e.target)&&!navToggle.contains(e.target))closeNav()});
function openDialog(dialog){closeNav();dialog.showModal();document.body.style.overflow='hidden'}$$('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));$$('dialog').forEach(d=>{d.addEventListener('close',()=>{document.body.style.overflow=''});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
$$('[data-reserve]').forEach(b=>b.addEventListener('click',()=>openDialog($('#reservation-dialog'))));$$('[data-menu]').forEach(b=>b.addEventListener('click',()=>{const f=$('#menu-dialog iframe');if(!f.src)f.src=f.dataset.src;openDialog($('#menu-dialog'))}));$('[data-info]').addEventListener('click',()=>openDialog($('#info-dialog')));
const reservationForm=$('#reservation-form'),dateInput=$('input[name=date]'),periodInput=$('select[name=period]');const nowParts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const datePart=t=>nowParts.find(p=>p.type===t).value;dateInput.min=`${datePart('year')}-${datePart('month')}-${datePart('day')}`;
function checkReservation(){const date=dateInput.value;const hint=$('#reservation-hint');hint.classList.remove('error');dateInput.setCustomValidity('');periodInput.setCustomValidity('');if(!date){hint.textContent='Reserva sujeita à confirmação da equipe.';return true}const weekday=new Date(`${date}T12:00:00`).getDay();let message='';if(weekday===0||weekday===1)message='A casa fecha aos domingos e às segundas. Escolha outro dia ou converse diretamente com a equipe.';else if(periodInput.value==='Almoço'&&(weekday===2||weekday===3))message='Às terças e quartas, recebemos você no jantar. Escolha jantar ou outro dia para o almoço.';if(message){hint.textContent=message;hint.classList.add('error');(weekday===0||weekday===1?dateInput:periodInput).setCustomValidity(message);return false}hint.textContent='Reserva sujeita à confirmação da equipe. Em feriados, confirme o funcionamento.';return true}
dateInput.addEventListener('change',checkReservation);periodInput.addEventListener('change',checkReservation);reservationForm.addEventListener('submit',e=>{e.preventDefault();if(!checkReservation()||!reservationForm.reportValidity())return;const d=new FormData(reservationForm),date=new Date(`${d.get('date')}T12:00:00`).toLocaleDateString('pt-BR');const message=`Olá, Pinho’s Bistrô! Sou ${String(d.get('name')).trim()} e gostaria de consultar uma reserva para ${d.get('guests')} pessoa(s), no dia ${date}, para ${String(d.get('period')).toLowerCase()}. Vocês têm disponibilidade?`;window.open('https://wa.me/5519995076736?text='+encodeURIComponent(message),'_blank','noopener,noreferrer');$('#reservation-hint').textContent='Continue a conversa na aba do WhatsApp. Sua reserva será confirmada pela equipe.'});
const gallery=[['assets/ambiente.webp','O ambiente do Pinho’s Bistrô'],['assets/cordon-bleu.webp','Cordon Bleu servido no Pinho’s'],['assets/sobremesa.webp','Sobremesa de chocolate servida na casa'],['assets/detalhe.webp','Os detalhes da experiência à mesa']];let galleryIndex=0;function showGallery(i){galleryIndex=(i+gallery.length)%gallery.length;$('#gallery-dialog>img').src=gallery[galleryIndex][0];$('#gallery-dialog>img').alt=gallery[galleryIndex][1];$('#gallery-count').textContent=`${galleryIndex+1} / ${gallery.length}`}
$$('[data-gallery]').forEach(b=>b.addEventListener('click',()=>{showGallery(+b.dataset.gallery);openDialog($('#gallery-dialog'))}));$('#gallery-prev').addEventListener('click',()=>showGallery(galleryIndex-1));$('#gallery-next').addEventListener('click',()=>showGallery(galleryIndex+1));$('#gallery-dialog').addEventListener('keydown',e=>{if(e.key==='ArrowRight')showGallery(galleryIndex+1);if(e.key==='ArrowLeft')showGallery(galleryIndex-1)});
