const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)');if(!reducedMotion.matches&&'IntersectionObserver'in window){document.body.classList.add('motion-ready');const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.08});$$('.reveal').forEach(el=>observer.observe(el));setTimeout(()=>$$('.reveal').forEach(el=>el.classList.add('visible')),7000)}
if(matchMedia('(hover: hover) and (pointer: fine)').matches&&!reducedMotion.matches){$$('.tilt-surface').forEach(el=>{let raf=0;el.addEventListener('pointermove',e=>{if(raf)cancelAnimationFrame(raf);raf=requestAnimationFrame(()=>{const r=el.getBoundingClientRect();const x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;el.style.transform=`perspective(1000px) rotateY(${x*6}deg) rotateX(${-y*6}deg)`})});el.addEventListener('pointerleave',()=>{cancelAnimationFrame(raf);el.style.transform=''})})}
